  export const filter: $FilterFunction<
    OrderedStruct.Filter,
    Omit<OrderedStruct, "$type">
  > = (filter, value) => {
    if (
      filter.$identifier !== undefined &&
      !$filterIdentifier(filter.$identifier, value.$identifier())
    ) {
      return false;
    }
    if (
      filter.orderedC !== undefined &&
      !$filterString(filter.orderedC, value.orderedC)
    ) {
      return false;
    }
    if (
      filter.orderedB !== undefined &&
      !$filterString(filter.orderedB, value.orderedB)
    ) {
      return false;
    }
    if (
      filter.orderedA !== undefined &&
      !$filterString(filter.orderedA, value.orderedA)
    ) {
      return false;
    }
    return true;
  };

