  export const fromJson: $FromJsonFunction<
    TermsStruct,
    Omit<TermsStruct.Json, "$type">
  > = ($json) =>
    $sequenceRecord({
      $identifier: Either.of<Error, BlankNode | NamedNode>(
        $json["@id"].startsWith("_:")
          ? dataFactory.blankNode($json["@id"].substring(2))
          : dataFactory.namedNode($json["@id"]),
      ),
      blankNodeTerm: Maybe.fromNullable($json["blankNodeTerm"])
        .map((item) =>
          Either.of<Error, BlankNode>(
            dataFactory.blankNode(item.substring(2)),
          ).map((item) => Maybe.of(item)),
        )
        .orDefault(Either.of(Maybe.empty())),
      booleanTerm: Maybe.fromNullable($json["booleanTerm"])
        .map((item) =>
          Either.of<Error, boolean>(item).map((item) => Maybe.of(item)),
        )
        .orDefault(Either.of(Maybe.empty())),
      dateTerm: Maybe.fromNullable($json["dateTerm"])
        .map((item) =>
          Either.encase<Error, Date>(() => new Date(item)).map((item) =>
            Maybe.of(item),
          ),
        )
        .orDefault(Either.of(Maybe.empty())),
      dateTimeTerm: Maybe.fromNullable($json["dateTimeTerm"])
        .map((item) =>
          Either.encase<Error, Date>(() => new Date(item)).map((item) =>
            Maybe.of(item),
          ),
        )
        .orDefault(Either.of(Maybe.empty())),
      doubleTerm: Maybe.fromNullable($json["doubleTerm"])
        .map((item) =>
          Either.of<Error, number>(item).map((item) => Maybe.of(item)),
        )
        .orDefault(Either.of(Maybe.empty())),
      identifierTerm: Maybe.fromNullable($json["identifierTerm"])
        .map((item) =>
          Either.of<Error, BlankNode | NamedNode>(
            item.startsWith("_:")
              ? dataFactory.blankNode(item.substring(2))
              : dataFactory.namedNode(item),
          ).map((item) => Maybe.of(item)),
        )
        .orDefault(Either.of(Maybe.empty())),
      iriTerm: Maybe.fromNullable($json["iriTerm"])
        .map((item) =>
          Either.of<Error, NamedNode>(dataFactory.namedNode(item)).map((item) =>
            Maybe.of(item),
          ),
        )
        .orDefault(Either.of(Maybe.empty())),
      langStringTerm: Maybe.fromNullable($json["langStringTerm"])
        .map((item) =>
          Either.of<Error, Literal>(
            dataFactory.literal(item["@value"], item["@language"]),
          ).map((item) => Maybe.of(item)),
        )
        .orDefault(Either.of(Maybe.empty())),
      literalTerm: Maybe.fromNullable($json["literalTerm"])
        .map((item) =>
          Either.of<Error, Literal>(
            dataFactory.literal(
              item["@value"],
              item["@language"] !== undefined
                ? item["@language"]
                : item["@type"] !== undefined
                  ? dataFactory.namedNode(item["@type"]!)
                  : undefined,
            ),
          ).map((item) => Maybe.of(item)),
        )
        .orDefault(Either.of(Maybe.empty())),
      stringTerm: Maybe.fromNullable($json["stringTerm"])
        .map((item) =>
          Either.of<Error, string>(item).map((item) => Maybe.of(item)),
        )
        .orDefault(Either.of(Maybe.empty())),
      term: Maybe.fromNullable($json["term"])
        .map((item) =>
          Either.of<Error, BlankNode | NamedNode | Literal>(
            item.$type === "Literal"
              ? dataFactory.literal(
                  item["@value"],
                  item["@language"] !== undefined
                    ? item["@language"]
                    : item["@type"] !== undefined
                      ? dataFactory.namedNode(item["@type"]!)
                      : undefined,
                )
              : item.$type === "NamedNode"
                ? dataFactory.namedNode(item["@id"])
                : dataFactory.blankNode(item["@id"].substring(2)),
          ).map((item) => Maybe.of(item)),
        )
        .orDefault(Either.of(Maybe.empty())),
    }).chain(TermsStruct.create);

